installer-gui-script.script:
__VERSION_CHECK_SCRIPT__

function earthInstallationCheck() {
    var plistPath = "/Applications/Earth.app/Contents/Info.plist";
    try {
        if (!system.files.fileExistsAtPath("/Applications/Earth.app")) {
            return true;
        }
        var installed = system.files.plistAtPath(plistPath);
        var version = installed && (typeof installed.EarthVersion !== "undefined" ?
            installed.EarthVersion : installed.CFBundleShortVersionString);
        var comparison = earthCompareVersions(version, "__VERSION__");
        if (comparison !== null && comparison <= 0) {
            return true;
        }
        my.result.type = "Fatal";
        my.result.title = "无法替换已安装的 Earth";
        my.result.message = comparison === null ?
            "无法读取或验证已安装应用的版本，安装已取消。请先检查现有应用，必要时手动卸载后重新安装。" :
            "已安装更新版本的 Earth，安装已取消以防止降级。";
        return false;
    } catch (error) {
        my.result.type = "Fatal";
        my.result.title = "无法验证 Earth 版本";
        my.result.message = "无法安全读取已安装应用的信息，安装已取消。现有应用不会被替换。";
        return false;
    }
}
